const str=(x,n=2000)=>typeof x==='string'&&x.length<=n;
const id=x=>str(x,80)&&/^[A-Za-z0-9][A-Za-z0-9_-]*$/.test(x)&&!['constructor','prototype','__proto__'].includes(x);
const mark=x=>['sun','moon'].includes(x),mode=x=>pairModes.includes(x);
