 const tasks=keys.map(key=>{const has=own(root.tasks,key),w=has?root.tasks[key]:null,t=has&&validPairWork(w)?w.source:root.source.tasks[key];return {id:key,title:validPairTask(t)?t.title:key,unreadable:has?!validPairWork(w):!validPairTask(t)};});
