 return {status:'ready',root,source:root.source,tasks,work:validPairWork(root.tasks[root.taskId])?root.tasks[root.taskId]:null,current:readableRuns.find(x=>x.entry.id===root.currentRun[root.mode]&&x.entry.mode===root.mode)?.entry||null,readableRuns,unreadableRuns};
