export function pairBranch(r){if(!rootShape(r)||r.branch.first===null)return null;const first=r.branch.first,second=r.branch.second,index=r.source.slots.indexOf(first),firstNumerator=pairCounts(r.source.slots)[first],remaining=pairRemaining(r.source.slots,r.mode,index<0?null:index),secondDenominator=r.mode==='keep'?5:6,secondNumerator=second===null||index<0?null:remaining.counts[second];return {first,second,firstNumerator,firstDenominator:6,secondNumerator,secondDenominator,numerator:secondNumerator===null?null:firstNumerator*secondNumerator,denominator:6*secondDenominator,remaining,possible:index>=0&&(second===null||secondNumerator>0),facts:secondNumerator===null?[]:[[firstNumerator,secondNumerator],[6,secondDenominator]]};}
function workFrom(t){return {source:clone(t),draft:Array(t.kind==='fraction'?2:t.kind==='counts'?3:1).fill(''),helpStage:0,support:Object.fromEntries(supportKeys.map(k=>[k,false])),checks:[],firstKept:null,checkView:null,feedback:''};}
function markVisible(r){if(r?.page==='results')r.theorySeen=true;const w=validPairWork(r?.tasks?.[r.taskId])?r.tasks[r.taskId]:null;if(r?.page==='tree'&&w){if(!r.folded){w.support.learn=true;if(w.source.guided.length)w.support.guided=true;}if(r.treeSeen)w.support.tree=true;if(r.theorySeen)w.support.theory=true;}}
const fits=(s,o)=>recoveryFitsProgressLimits(s)&&(!o.canExport||o.canExport(s)===true);
function change(state,fn,o={},expose=false){try{if(own(state,'seedPairs')&&!rootShape(state.seedPairs))return false;const c=clone(state),result=fn(c);if(!result||!rootShape(c.seedPairs))return false;markVisible(c.seedPairs);const fs=expose?pairFacts(c):[];if(fs.length)o.exposeFacts?.(fs,c);if(!fits(c,o))return false;if(fs.length)o.exposeFacts?.(fs,state);state.seedPairs=c.seedPairs;return result;}catch{return false;}}
