export const pairInteger=raw=>safeDraft(raw)&&/^[0-9]+$/.test(raw.trim())&&int(Number(raw.trim()),0,999)?Number(raw.trim()):null;
function parsed(t,raw){if(!rawShape(t,raw))return null;if(t.kind==='choice')return t.options.some(x=>x.id===raw[0])?raw[0]:null;const values=raw.map(pairInteger);return values.every(x=>x!==null)&&(t.kind!=='fraction'||values[1]>0)?values:null;}
