export function checkPair(s,raw,o={}){const view=pairView(s),w=view.work;if(!w)return {recorded:false,feedback:'This saved question is unavailable. Your earlier work remains in notes; choose another question.'};const answer=parsed(w.source,raw);if(answer===null)return {recorded:false,feedback:pairInputMessage};const result=update(s,r=>{markVisible(r);const t=pairView({seedPairs:r}).work,correct=matches(t.source,answer,t.source.key),tag=correct?null:t.source.wrong.find(x=>matches(t.source,answer,x.key));const record={source:clone(t.source),raw:clone(raw),parsed:clone(answer),correct,code:correct?'fits':tag?.id||'try-again',feedback:correct?'This answer fits the question.':tag?.feedback||t.source.retry,support:clone(t.support),context:{mode:r.mode,branch:clone(r.branch),experimentSlots:clone(r.source.slots)}};const evicted=t.checks.length===4;t.checks=[...t.checks,record].slice(-4);t.firstKept??=clone(record);t.draft=clone(raw);t.checkView='latest';t.feedback=record.feedback;return {recorded:true,...clone(record),evicted,feedback:record.feedback+(evicted?' The oldest of the latest four checks was replaced; your first kept check remains.':'')};},o,true);return result||{recorded:false,feedback:'This check could not fit safely in a notes download. Your earlier work remains unchanged.'};}
export const pairHelp=(s,o={})=>update(s,r=>{const w=pairView({seedPairs:r}).work;if(!w)return false;w.helpStage=w.helpStage===3?1:w.helpStage+1;w.support[w.helpStage===1?'hint':w.helpStage===2?'example':'skip']=true;w.feedback=w.helpStage===1?w.source.hint:w.helpStage===2?w.source.suggested:w.source.skip;return true;},o,true);
